import zlib, struct, os, glob

def raw_pigz(data, level=6, bs=128*1024, independent=False):
    if not data:
        c=zlib.compressobj(level,zlib.DEFLATED,-15,8,zlib.Z_DEFAULT_STRATEGY); return c.flush(zlib.Z_FINISH)
    out=b''; prev=b''
    for pos in range(0,len(data),bs):
        chunk=data[pos:pos+bs]
        last=pos+bs>=len(data)
        if independent or not prev:
            c=zlib.compressobj(level,zlib.DEFLATED,-15,8,zlib.Z_DEFAULT_STRATEGY)
        else:
            c=zlib.compressobj(level,zlib.DEFLATED,-15,8,zlib.Z_DEFAULT_STRATEGY,zdict=prev[-32768:])
        part=c.compress(chunk)+c.flush(zlib.Z_FINISH if last else zlib.Z_SYNC_FLUSH)
        if not last:
            if independent:
                out+=part + b'\x00\x00\x00\xff\xff'
            else:
                out+=part[:-4]
        else:
            out+=part
        prev += chunk
    return out

def gz(data,level=6,bs=128*1024,independent=False):
    xfl=4 if level==1 else 2 if level==9 else 0
    return b'\x1f\x8b\x08\x00\0\0\0\0'+bytes([xfl,3])+raw_pigz(data,level,bs,independent)+struct.pack('<II',zlib.crc32(data)&0xffffffff,len(data)&0xffffffff)
for f in ['pattern200k','rand200k']:
 data=open(f,'rb').read()
 for suffix,l,b,i in [('cn',6,128*1024,False),('cnb32',6,32*1024,False),('cni',6,128*1024,True),('cni_-b_32',6,32*1024,True),('cn0',0,128*1024,False),('cn1',1,128*1024,False),('cn9',9,128*1024,False)]:
  matches=glob.glob(f'{f}_*{suffix}*.gz')
  path=matches[0]
  orig=open(path,'rb').read(); model=gz(data,l,b,i)
  print(f,suffix,len(orig),len(model),orig==model,next((j for j,(a,b) in enumerate(zip(orig,model)) if a!=b),None))
