    bool orig_unknown;
    bool multi;
} Meta;

static void buf_init(Buffer *b) { b->data = NULL; b->len = b->cap = 0; }
static void buf_free(Buffer *b) { free(b->data); b->data = NULL; b->len = b->cap = 0; }
static void buf_reserve(Buffer *b, size_t add) {
    if (add > SIZE_MAX - b->len) { fprintf(stderr, "%s: abort: out of memory\n", progname); exit(22); }
    size_t need = b->len + add;
    if (need <= b->cap) return;
    size_t cap = b->cap ? b->cap : 4096;
    while (cap < need) {
        if (cap > SIZE_MAX / 2) { cap = need; break; }
        cap *= 2;
    }
    unsigned char *p = (unsigned char *)realloc(b->data, cap);
    if (!p) { fprintf(stderr, "%s: abort: out of memory\n", progname); exit(22); }
    b->data = p; b->cap = cap;
}
static void buf_append(Buffer *b, const void *src, size_t len) {
    if (len == 0) return;
    buf_reserve(b, len);
    memcpy(b->data + b->len, src, len);
    b->len += len;
}
static void buf_put8(Buffer *b, unsigned val) { unsigned char c = (unsigned char)val; buf_append(b, &c, 1); }
static void buf_put16le(Buffer *b, uint16_t v) { unsigned char x[2] = { (unsigned char)v, (unsigned char)(v >> 8) }; buf_append(b, x, 2); }
static void buf_put32le(Buffer *b, uint32_t v) { unsigned char x[4] = { (unsigned char)v, (unsigned char)(v >> 8), (unsigned char)(v >> 16), (unsigned char)(v >> 24) }; buf_append(b, x, 4); }
static void buf_put64le(Buffer *b, uint64_t v) { for (int i = 0; i < 8; i++) buf_put8(b, (unsigned)(v >> (8*i))); }

static uint16_t rd16(const unsigned char *p) { return (uint16_t)p[0] | ((uint16_t)p[1] << 8); }
static uint32_t rd32(const unsigned char *p) { return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24); }
static uint64_t rd64(const unsigned char *p) { uint64_t v = 0; for (int i=7;i>=0;i--) v = (v << 8) | p[i]; return v; }

static const char *base_name(const char *path) {
    const char *s = strrchr(path, '/');
    return s ? s + 1 : path;
}

static bool ends_with(const char *s, const char *suf) {
    size_t n = strlen(s), m = strlen(suf);
    return n >= m && memcmp(s + n - m, suf, m) == 0;
}

static char *xstrdup(const char *s) {
    char *p = strdup(s ? s : "");
    if (!p) { fprintf(stderr, "%s: abort: out of memory\n", progname); exit(22); }
    return p;
}

static void msg_abort(const Options *opt, const char *fmt, ...) {
    if (!opt || !opt->quiet) {
        va_list ap;
        va_start(ap, fmt);
        fprintf(stderr, "%s: abort: ", progname);
        vfprintf(stderr, fmt, ap);
        fprintf(stderr, "\n");
        va_end(ap);
    }
    exit(22);
}

static void warn_msg(const Options *opt, const char *fmt, ...) {
    if (opt && opt->quiet) return;
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "%s: ", progname);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static void skip_msg(const Options *opt, const char *fmt, ...) {
    if (opt && opt->quiet) return;
    va_list ap;
    va_start(ap, fmt);
    fprintf(stderr, "%s: skipping: ", progname);
    vfprintf(stderr, fmt, ap);
    fprintf(stderr, "\n");
    va_end(ap);
}

static void vec_push(StrVec *v, char *s) {
    if (v->n == v->cap) {
        int nc = v->cap ? v->cap * 2 : 16;
        char **nv = (char **)realloc(v->v, (size_t)nc * sizeof(char*));
        if (!nv) { fprintf(stderr, "%s: abort: out of memory\n", progname); exit(22); }
        v->v = nv; v->cap = nc;
    }
    v->v[v->n++] = s;
}

static void split_env(StrVec *toks, const char *env) {
    if (!env) return;
    const char *p = env;
    while (*p) {
        while (isspace((unsigned char)*p)) p++;
        if (!*p) break;
        const char *start = p;
        while (*p && !isspace((unsigned char)*p)) p++;
        size_t n = (size_t)(p - start);
        char *s = (char *)malloc(n + 1);
        if (!s) { fprintf(stderr, "%s: abort: out of memory\n", progname); exit(22); }
        memcpy(s, start, n); s[n] = 0;
        vec_push(toks, s);
    }
}

static int parse_num(const Options *opt, const char *s) {
    if (!s || !*s) msg_abort(opt, "invalid numeric parameter: %s", s ? s : "");
    unsigned long val = 0;
    for (const char *p = s; *p; p++) {
        if (!isdigit((unsigned char)*p)) msg_abort(opt, "invalid numeric parameter: %s", s);
        val = val * 10 + (unsigned long)(*p - '0');
        if (val > 1000000000UL) msg_abort(opt, "invalid numeric parameter: %s", s);
    }
    return (int)val;
}

static void usage(void) {
    fputs(
"Usage: pigz [options] [files ...]\n"
"  will compress files in place, adding the suffix '.gz'. If no files are\n"
"  specified, stdin will be compressed to stdout. pigz does what gzip does,\n"
"  but spreads the work over multiple processors and cores when compressing.\n"
"\n"
"Options:\n"
"  -0 to -9, -11        Compression level (level 11, zopfli, is much slower)\n"
"  --fast, --best       Compression levels 1 and 9 respectively\n"
"  -A, --alias xxx      Use xxx as the name for any --zip entry from stdin\n"
"  -b, --blocksize mmm  Set compression block size to mmmK (default 128K)\n"
"  -c, --stdout         Write all processed output to stdout (won't delete)\n"
"  -C, --comment ccc    Put comment ccc in the gzip or zip header\n"
"  -d, --decompress     Decompress the compressed input\n"
"  -f, --force          Force overwrite, compress .gz, links, and to terminal\n"
"  -F  --first          Do iterations first, before block split for -11\n"
"  -h, --help           Display a help screen and quit\n"
"  -H, --huffman        Use only Huffman coding for compression\n"
"  -i, --independent    Compress blocks independently for damage recovery\n"
"  -I, --iterations n   Number of iterations for -11 optimization\n"
"  -J, --maxsplits n    Maximum number of split blocks for -11\n"
"  -k, --keep           Do not delete original file after processing\n"
"  -K, --zip            Compress to PKWare zip (.zip) single entry format\n"
"  -l, --list           List the contents of the compressed input\n"
"  -L, --license        Display the pigz license and quit\n"
"  -m, --no-time        Do not store or restore mod time\n"
"  -M, --time           Store or restore mod time\n"
"  -n, --no-name        Do not store or restore file name or mod time\n"
"  -N, --name           Store or restore file name and mod time\n"
"  -O  --oneblock       Do not split into smaller blocks for -11\n"
"  -p, --processes n    Allow up to n compression threads (default is the\n"
"                       number of online processors, or 8 if unknown)\n"
"  -q, --quiet          Print no messages, even on error\n"
"  -r, --recursive      Process the contents of all subdirectories\n"
"  -R, --rsyncable      Input-determined block locations for rsync\n"
"  -S, --suffix .sss    Use suffix .sss instead of .gz (for compression)\n"
"  -t, --test           Test the integrity of the compressed input\n"
"  -U, --rle            Use run-length encoding for compression\n"
"  -v, --verbose        Provide more verbose output\n"
"  -V  --version        Show the version of pigz\n"
"  -Y  --synchronous    Force output file write to permanent storage\n"
"  -z, --zlib           Compress to zlib (.zz) instead of gzip format\n"
"  --                   All arguments after \"--\" are treated as files\n", stderr);
}

static void license_out(void) {
    printf("pigz %s\n", VERSION);
    printf("Copyright (C) 2007-2023 Mark Adler\n");
    printf("Subject to the terms of the zlib license.\n");
    printf("No warranty is provided or implied.\n");
}

static bool is_long(const char *s, const char *name) { return strcmp(s, name) == 0; }

static char *need_param(Options *opt, StrVec *toks, int *idx, const char *optname, const char *rest) {
    if (rest && *rest) return (char *)rest;
    if (*idx + 1 >= toks->n || toks->v[*idx + 1][0] == '-') msg_abort(opt, "missing parameter after %s", optname);
    (*idx)++;
    return toks->v[*idx];
}

static void set_level_or_abort(Options *opt, int lev) {
    if (!((lev >= 0 && lev <= 9) || lev == 11)) msg_abort(opt, "only levels 0..9 and 11 are allowed");
    opt->level = lev;
}

static void parse_options(int argc, char **argv, Options *opt, StrVec *files) {
    memset(opt, 0, sizeof(*opt));
    opt->level = 6; opt->block_k = 128; opt->processes = 0; opt->strategy = Z_DEFAULT_STRATEGY;
    opt->save_name = true; opt->save_time = true;
    opt->alias = xstrdup("-");

    const char *bn = base_name(argv[0]);
    progname = bn && *bn ? bn : "executable";
    if (strstr(progname, "unpigz") || strstr(progname, "gunzip")) opt->decompress = true;

    StrVec toks = {0};
    split_env(&toks, getenv("GZIP"));
    split_env(&toks, getenv("PIGZ"));
    for (int i=1;i<argc;i++) vec_push(&toks, argv[i]);

    bool dashdash = false;
    for (int i=0; i<toks.n; i++) {
        char *arg = toks.v[i];
        if (dashdash) { vec_push(files, arg); continue; }
        if (strcmp(arg, "--") == 0) { dashdash = true; continue; }
        if (arg[0] != '-' || arg[1] == '\0') { vec_push(files, arg); continue; }
        if (arg[1] == '-') {
            if (is_long(arg, "--help")) { usage(); exit(0); }
            else if (is_long(arg, "--version")) { printf("pigz %s\n", VERSION); if (opt->verbose) printf("zlib %s\n", "1.2.11"); exit(0); }
            else if (is_long(arg, "--license")) { license_out(); exit(0); }
            else if (is_long(arg, "--fast")) opt->level = 1;
            else if (is_long(arg, "--best")) opt->level = 9;
            else if (is_long(arg, "--stdout") || is_long(arg, "--to-stdout")) opt->stdout_mode = true;
            else if (is_long(arg, "--decompress") || is_long(arg, "--uncompress")) opt->decompress = true;
            else if (is_long(arg, "--keep")) opt->keep = true;
            else if (is_long(arg, "--force")) opt->force = true;
            else if (is_long(arg, "--quiet") || is_long(arg, "--silent")) opt->quiet = true;
            else if (is_long(arg, "--recursive")) opt->recursive = true;
            else if (is_long(arg, "--list")) { opt->list = true; opt->decompress = true; }
            else if (is_long(arg, "--test")) { opt->test = true; opt->decompress = true; }
            else if (is_long(arg, "--zlib")) opt->zlib_mode = true;
            else if (is_long(arg, "--zip")) opt->zip_mode = true;
            else if (is_long(arg, "--independent")) opt->independent = true;
            else if (is_long(arg, "--rsyncable")) { /* accepted */ }
            else if (is_long(arg, "--huffman")) opt->strategy = Z_HUFFMAN_ONLY;
            else if (is_long(arg, "--rle")) opt->strategy = Z_RLE;
            else if (is_long(arg, "--no-name")) { opt->save_name=false; opt->save_time=false; opt->name_explicit=true; opt->time_explicit=true; }
            else if (is_long(arg, "--name")) { opt->save_name=true; opt->save_time=true; opt->name_explicit=true; opt->time_explicit=true; }
            else if (is_long(arg, "--no-time")) { opt->save_time=false; opt->time_explicit=true; }
            else if (is_long(arg, "--time")) { opt->save_time=true; opt->time_explicit=true; }
            else if (is_long(arg, "--synchronous")) opt->syncout = true;
            else if (is_long(arg, "--first") || is_long(arg, "--oneblock")) { /* zopfli-only no-op */ }
            else if (is_long(arg, "--alias")) { free(opt->alias); opt->alias = xstrdup(need_param(opt, &toks, &i, "--alias", NULL)); }
            else if (is_long(arg, "--blocksize")) { int n=parse_num(opt, need_param(opt,&toks,&i,"--blocksize",NULL)); if(n<32) msg_abort(opt,"block size too small (must be >= 32K)"); opt->block_k=n; }
            else if (is_long(arg, "--comment")) { free(opt->comment); opt->comment = xstrdup(need_param(opt,&toks,&i,"--comment",NULL)); }
            else if (is_long(arg, "--processes")) { int n=parse_num(opt, need_param(opt,&toks,&i,"--processes",NULL)); if(n<1) msg_abort(opt,"invalid number of processes: %d", n); opt->processes=n; }
            else if (is_long(arg, "--suffix")) { char *s=need_param(opt,&toks,&i,"--suffix",NULL); if(!*s) msg_abort(opt,"suffix cannot be empty"); free(opt->suffix); opt->suffix=xstrdup(s); opt->suffix_set=true; }
            else if (is_long(arg, "--iterations")) { (void)parse_num(opt, need_param(opt,&toks,&i,"--iterations",NULL)); }
            else if (is_long(arg, "--maxsplits")) { (void)parse_num(opt, need_param(opt,&toks,&i,"--maxsplits",NULL)); }
            else msg_abort(opt, "invalid option: %s", arg);
            continue;
        }
        /* short options, clustered */
        for (int j=1; arg[j]; j++) {
            char c = arg[j];
            if (isdigit((unsigned char)c)) {
                if (c == '1' && isdigit((unsigned char)arg[j+1])) {
                    int k = j; int val = 0;
                    while (isdigit((unsigned char)arg[k])) { val = val*10 + (arg[k]-'0'); k++; }
                    set_level_or_abort(opt, val);
                    j = k - 1;
                } else {
                    set_level_or_abort(opt, c - '0');
                }
                continue;
            }
            switch (c) {
                case 'A': { char *s=need_param(opt,&toks,&i,"-A",arg+j+1); free(opt->alias); opt->alias=xstrdup(s); j=(int)strlen(arg)-1; break; }
                case 'b': { char *s=need_param(opt,&toks,&i,"-b",arg+j+1); int n=parse_num(opt,s); if(n<32) msg_abort(opt,"block size too small (must be >= 32K)"); opt->block_k=n; j=(int)strlen(arg)-1; break; }
                case 'c': opt->stdout_mode = true; break;
                case 'C': { char *s=need_param(opt,&toks,&i,"-C",arg+j+1); free(opt->comment); opt->comment=xstrdup(s); j=(int)strlen(arg)-1; break; }
                case 'd': opt->decompress = true; break;
                case 'f': opt->force = true; break;
                case 'F': break;
                case 'h': usage(); exit(0);
                case 'H': opt->strategy = Z_HUFFMAN_ONLY; break;
                case 'i': opt->independent = true; break;
                case 'I': { char *s=need_param(opt,&toks,&i,"-I",arg+j+1); (void)parse_num(opt,s); j=(int)strlen(arg)-1; break; }
                case 'J': { char *s=need_param(opt,&toks,&i,"-J",arg+j+1); (void)parse_num(opt,s); j=(int)strlen(arg)-1; break; }
                case 'k': opt->keep = true; break;
                case 'K': opt->zip_mode = true; break;
                case 'l': opt->list = true; opt->decompress = true; break;
                case 'L': license_out(); exit(0);
                case 'm': opt->save_time = false; opt->time_explicit = true; break;
                case 'M': opt->save_time = true; opt->time_explicit = true; break;
                case 'n': opt->save_name = false; opt->save_time = false; opt->name_explicit = true; opt->time_explicit = true; break;
                case 'N': opt->save_name = true; opt->save_time = true; opt->name_explicit = true; opt->time_explicit = true; break;
                case 'O': break;
                case 'p': { char *s=need_param(opt,&toks,&i,"-p",arg+j+1); int n=parse_num(opt,s); if(n<1) msg_abort(opt,"invalid number of processes: %d", n); opt->processes=n; j=(int)strlen(arg)-1; break; }
                case 'q': opt->quiet = true; break;
                case 'r': opt->recursive = true; break;
                case 'R': break;
                case 'S': { char *s=need_param(opt,&toks,&i,"-S",arg+j+1); if(!*s) msg_abort(opt,"suffix cannot be empty"); free(opt->suffix); opt->suffix=xstrdup(s); opt->suffix_set=true; j=(int)strlen(arg)-1; break; }
                case 't': opt->test = true; opt->decompress = true; break;
                case 'U': opt->strategy = Z_RLE; break;
                case 'v': opt->verbose = true; break;
                case 'V': printf("pigz %s\n", VERSION); if (opt->verbose) printf("zlib %s\n", "1.2.11"); exit(0);
                case 'Y': opt->syncout = true; break;
                case 'z': opt->zlib_mode = true; break;
                default: {
                    char tmp[4] = {'-', c, 0, 0};
                    msg_abort(opt, "invalid option: %s", tmp);
                }
            }
        }
    }
    if (opt->decompress) {
        if (!opt->name_explicit) opt->save_name = false;
        if (!opt->time_explicit) opt->save_time = false;
    }
}

static bool read_stream(FILE *f, Buffer *out) {
    unsigned char tmp[32768];
    for (;;) {
        size_t n = fread(tmp, 1, sizeof(tmp), f);
        if (n) buf_append(out, tmp, n);
        if (n < sizeof(tmp)) {
            if (ferror(f)) return false;
            return true;
        }
    }
}

static bool read_file_buf(const char *path, Buffer *out) {
    FILE *f = fopen(path, "rb");
    if (!f) return false;
    bool ok = read_stream(f, out);
    if (fclose(f) != 0) ok = false;
    return ok;
}

static bool write_file_buf(const char *path, const Buffer *b, mode_t mode, time_t mtime, bool set_time, bool syncout) {
    int fd = open(path, O_WRONLY|O_CREAT|O_TRUNC, mode ? (mode & 0777) : 0666);
    if (fd < 0) return false;
    size_t off = 0;
    while (off < b->len) {
        ssize_t got = write(fd, b->data + off, b->len - off);
        if (got < 0) { close(fd); return false; }
        off += (size_t)got;
    }
    if (syncout) fsync(fd);
    if (close(fd) != 0) return false;
    chmod(path, mode ? (mode & 0777) : 0666);
    if (set_time) {
        struct utimbuf ut; ut.actime = mtime; ut.modtime = mtime; utime(path, &ut);
    }
    return true;
}

static void append_deflate_part(Buffer *out, const unsigned char *data, size_t len, int level, int strategy, int flush, const unsigned char *dict, size_t dict_len, bool strip_four) {
    z_stream s; memset(&s, 0, sizeof(s));
    if (deflateInit2(&s, level, Z_DEFLATED, -15, 8, strategy) != Z_OK) return;
    if (dict && dict_len) deflateSetDictionary(&s, dict, (uInt)dict_len);
    s.next_in = (Bytef *)data; s.avail_in = (uInt)len;
    unsigned char tmp[32768];
    Buffer part; buf_init(&part);
    int ret;
    do {
        s.next_out = tmp; s.avail_out = sizeof(tmp);
        ret = deflate(&s, flush);
        size_t have = sizeof(tmp) - s.avail_out;
        if (have) buf_append(&part, tmp, have);
    } while (ret != Z_STREAM_END && (s.avail_in != 0 || s.avail_out == 0));
    deflateEnd(&s);
    size_t n = part.len;
    if (strip_four && n >= 4) n -= 4;
    buf_append(out, part.data, n);
    buf_free(&part);
}

static void append_raw_deflate(Buffer *out, const unsigned char *data, size_t len, const Options *opt) {
    int level = opt->level == 11 ? 9 : opt->level;
    size_t bs = (size_t)opt->block_k * 1024U;
    if (bs == 0) bs = 128*1024U;
    if (len == 0) {
        append_deflate_part(out, data, 0, level, opt->strategy, Z_FINISH, NULL, 0, false);
        return;
    }
    for (size_t pos = 0; pos < len; pos += bs) {
        size_t n = len - pos; if (n > bs) n = bs;
        bool last = (pos + n == len);
        const unsigned char *dict = NULL; size_t dict_len = 0;
        if (!opt->independent && pos > 0) {
            dict_len = pos < 32768U ? pos : 32768U;
            dict = data + pos - dict_len;
        }
        if (opt->independent) {
            append_deflate_part(out, data + pos, n, level, opt->strategy, last ? Z_FINISH : Z_SYNC_FLUSH, NULL, 0, false);
            if (!last) {
                unsigned char mark[5] = {0,0,0,0xff,0xff};
                buf_append(out, mark, 5);
            }
        } else {
            append_deflate_part(out, data + pos, n, level, opt->strategy, last ? Z_FINISH : Z_SYNC_FLUSH, dict, dict_len, !last);
        }
    }
}

static void make_gzip(Buffer *out, const unsigned char *data, size_t len, const Options *opt, const char *inname, time_t mtime, bool is_stdin) {
    int level = opt->level == 11 ? 9 : opt->level;
    int xfl = (level == 1) ? 4 : (level == 9 ? 2 : 0);
    unsigned flg = 0;
    const char *fname = NULL;
    if (!is_stdin && opt->save_name && inname) { fname = base_name(inname); if (*fname) flg |= 8; }
    if (opt->comment) flg |= 16;
    buf_put8(out, 0x1f); buf_put8(out, 0x8b); buf_put8(out, 8); buf_put8(out, flg);
    buf_put32le(out, (!is_stdin && opt->save_time) ? (uint32_t)mtime : 0);
    buf_put8(out, xfl); buf_put8(out, 3);
    if (fname) { buf_append(out, fname, strlen(fname)); buf_put8(out, 0); }
    if (opt->comment) { buf_append(out, opt->comment, strlen(opt->comment)); buf_put8(out, 0); }
    append_raw_deflate(out, data, len, opt);
    uint32_t crc = crc32(0L, Z_NULL, 0); crc = crc32(crc, data, (uInt)len);
    buf_put32le(out, crc); buf_put32le(out, (uint32_t)len);
}

static int zlib_flg_for_level(int lev) {
    if (lev == 11) lev = 9;
    if (lev == 1) return 0x01;
    if (lev == 9) return 0xda;
    if (lev >= 6) return 0x5e;
    return 0x9c;
}

static void make_zlib_fmt(Buffer *out, const unsigned char *data, size_t len, const Options *opt) {
    buf_put8(out, 0x78); buf_put8(out, zlib_flg_for_level(opt->level));
    append_raw_deflate(out, data, len, opt);
    uint32_t ad = adler32(0L, Z_NULL, 0); ad = adler32(ad, data, (uInt)len);
    /* Adler-32 is stored big-endian */
    buf_put8(out, (ad >> 24) & 255); buf_put8(out, (ad >> 16) & 255); buf_put8(out, (ad >> 8) & 255); buf_put8(out, ad & 255);
}

static uint32_t dos_time_date(time_t t) {
    struct tm *tm = localtime(&t);
    if (!tm) return 0;
    int year = tm->tm_year + 1900; if (year < 1980) year = 1980;
    uint32_t tim = ((uint32_t)tm->tm_hour << 11) | ((uint32_t)tm->tm_min << 5) | ((uint32_t)tm->tm_sec / 2);
    uint32_t dat = ((uint32_t)(year - 1980) << 9) | ((uint32_t)(tm->tm_mon + 1) << 5) | (uint32_t)tm->tm_mday;
    return (dat << 16) | tim;
}

static void zip_extra_local(Buffer *out, uint32_t mtime) {
    buf_put16le(out, 0x0001); buf_put16le(out, 16);
    buf_put64le(out, 0); buf_put64le(out, 0);
    buf_put16le(out, 0x5455); buf_put16le(out, 5); buf_put8(out, 1); buf_put32le(out, mtime);
}
static void zip_extra_central(Buffer *out, uint32_t mtime) {
    buf_put16le(out, 0x5455); buf_put16le(out, 5); buf_put8(out, 1); buf_put32le(out, mtime);
}

static void make_zip(Buffer *out, const unsigned char *data, size_t len, const Options *opt, const char *inname, time_t mtime, bool is_stdin) {
    Buffer comp; buf_init(&comp); append_raw_deflate(&comp, data, len, opt);
    uint32_t crc = crc32(0L, Z_NULL, 0); crc = crc32(crc, data, (uInt)len);
    const char *zname;
    if (!is_stdin && opt->save_name && inname && *base_name(inname)) zname = base_name(inname);
    else zname = opt->alias ? opt->alias : "-";
    uint16_t nlen = (uint16_t)strlen(zname);
    uint32_t use_mtime = (!is_stdin && opt->save_time) ? (uint32_t)mtime : 0;
    time_t dost = (use_mtime ? (time_t)use_mtime : time(NULL));
    uint32_t dt = dos_time_date(dost);
    size_t local_off = out->len;
    (void)local_off;
    buf_put32le(out, 0x04034b50); buf_put16le(out, 45); buf_put16le(out, 8); buf_put16le(out, 8);
    buf_put16le(out, (uint16_t)(dt & 0xffff)); buf_put16le(out, (uint16_t)(dt >> 16));
    buf_put32le(out, 0); buf_put32le(out, 0xffffffffU); buf_put32le(out, 0xffffffffU);
    buf_put16le(out, nlen); buf_put16le(out, 29);
    buf_append(out, zname, nlen); zip_extra_local(out, use_mtime);
    buf_append(out, comp.data, comp.len);
    buf_put32le(out, 0x08074b50); buf_put32le(out, crc); buf_put64le(out, comp.len); buf_put64le(out, len);
    size_t cd_off = out->len;
    buf_put32le(out, 0x02014b50); buf_put16le(out, 0xff2d); buf_put16le(out, 45); buf_put16le(out, 8); buf_put16le(out, 8);
    buf_put16le(out, (uint16_t)(dt & 0xffff)); buf_put16le(out, (uint16_t)(dt >> 16));
    buf_put32le(out, crc); buf_put32le(out, (uint32_t)comp.len); buf_put32le(out, (uint32_t)len);
    buf_put16le(out, nlen); buf_put16le(out, 9); buf_put16le(out, opt->comment ? (uint16_t)strlen(opt->comment) : 0);
    buf_put16le(out, 0); buf_put16le(out, 0); buf_put32le(out, 0); buf_put32le(out, 0);
    buf_append(out, zname, nlen); zip_extra_central(out, use_mtime);
    if (opt->comment) buf_append(out, opt->comment, strlen(opt->comment));
    size_t cd_size = out->len - cd_off;
    buf_put32le(out, 0x06054b50); buf_put16le(out, 0); buf_put16le(out, 0); buf_put16le(out, 1); buf_put16le(out, 1);
    buf_put32le(out, (uint32_t)cd_size); buf_put32le(out, (uint32_t)cd_off); buf_put16le(out, 0);
    buf_free(&comp);
}

static bool inflate_raw_to_buf(const unsigned char *src, size_t srclen, Buffer *out, size_t *consumed) {
    z_stream s; memset(&s, 0, sizeof(s));
    if (inflateInit2(&s, -15) != Z_OK) return false;
    s.next_in = (Bytef *)src; s.avail_in = (uInt)srclen;
    unsigned char tmp[32768];
    int ret;
    do {
        s.next_out = tmp; s.avail_out = sizeof(tmp);
        ret = inflate(&s, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) { inflateEnd(&s); return false; }
        size_t have = sizeof(tmp) - s.avail_out;
        if (have) buf_append(out, tmp, have);
    } while (ret != Z_STREAM_END);
    if (consumed) *consumed = s.total_in;
    inflateEnd(&s);
    return true;
}

static bool inflate_zlib_to_buf(const unsigned char *src, size_t srclen, Buffer *out, size_t *consumed) {
    z_stream s; memset(&s, 0, sizeof(s));
    if (inflateInit(&s) != Z_OK) return false;
    s.next_in = (Bytef *)src; s.avail_in = (uInt)srclen;
    unsigned char tmp[32768]; int ret;
    do {
        s.next_out = tmp; s.avail_out = sizeof(tmp);
        ret = inflate(&s, Z_NO_FLUSH);
        if (ret != Z_OK && ret != Z_STREAM_END) { inflateEnd(&s); return false; }
        size_t have = sizeof(tmp) - s.avail_out;
        if (have) buf_append(out, tmp, have);
    } while (ret != Z_STREAM_END);
    if (consumed) *consumed = s.total_in;
    inflateEnd(&s);
    return true;
}

static char *read_cstring_header(const unsigned char *data, size_t len, size_t *pos) {
    size_t start = *pos;
    while (*pos < len && data[*pos]) (*pos)++;
    if (*pos >= len) return NULL;
    size_t n = *pos - start;
    char *s = (char *)malloc(n + 1); if (!s) return NULL;
    memcpy(s, data + start, n); s[n] = 0; (*pos)++;
    return s;
}

static int parse_gzip(const unsigned char *data, size_t len, Buffer *out, Meta *meta, bool list_only, char **errmsg) {
    (void)list_only;
    if (len == 0) { *errmsg = xstrdup("empty"); return -1; }
    size_t pos = 0; bool first = true; uint64_t total_out = 0; uint64_t total_comp = 0; int members = 0;
    memset(meta, 0, sizeof(*meta)); meta->format = 1; meta->method = 8;
    while (pos < len) {
        if (pos + 10 > len || data[pos] != 0x1f || data[pos+1] != 0x8b || data[pos+2] != 8) { *errmsg = xstrdup(first ? "unrecognized format" : "trailing garbage"); return -1; }
        unsigned flg = data[pos+3]; uint32_t mt = rd32(data+pos+4); pos += 10;
        if (flg & 4) { if (pos + 2 > len) { *errmsg=xstrdup("corrupted"); return -1; } unsigned xlen=rd16(data+pos); pos += 2 + xlen; if (pos > len) { *errmsg=xstrdup("corrupted"); return -1; } }
        char *fname = NULL;
        if (flg & 8) { fname = read_cstring_header(data, len, &pos); if (!fname) { *errmsg=xstrdup("corrupted"); return -1; } }
        if (flg & 16) { char *c = read_cstring_header(data, len, &pos); if (!c) { free(fname); *errmsg=xstrdup("corrupted"); return -1; } free(c); }
        if (flg & 2) { if (pos + 2 > len) { free(fname); *errmsg=xstrdup("corrupted"); return -1; } pos += 2; }
        size_t comp_start = pos; size_t consumed = 0; size_t out_before = out->len;
        if (!inflate_raw_to_buf(data + pos, len - pos, out, &consumed)) { free(fname); *errmsg=xstrdup("corrupted -- invalid deflate data"); return -1; }
        pos += consumed;
        if (pos + 8 > len) { free(fname); *errmsg=xstrdup("corrupted -- missing trailer"); return -1; }
        uint32_t expect_crc = rd32(data + pos); uint32_t expect_len = rd32(data + pos + 4); pos += 8;
        uint32_t crc = crc32(0L, Z_NULL, 0); crc = crc32(crc, out->data + out_before, (uInt)(out->len - out_before));
        if (crc != expect_crc) { free(fname); *errmsg=xstrdup("corrupted -- crc32 mismatch"); return -1; }
        if (((uint32_t)(out->len - out_before)) != expect_len) { free(fname); *errmsg=xstrdup("corrupted -- length mismatch"); return -1; }
        if (first) {
            meta->check = expect_crc; meta->mtime = mt; meta->has_mtime = mt != 0; meta->name = fname ? fname : NULL;
            meta->comp_size = consumed; meta->orig_size = expect_len;
        } else free(fname);
        total_out += expect_len; total_comp += consumed; members++; first = false;
        if (pos == len) break;
    }
    if (members > 1) { meta->multi = true; meta->orig_unknown = true; meta->orig_size = (uint32_t)meta->orig_size; meta->comp_size = len > 20 ? len - 20 : total_comp; }
    else { meta->orig_size = total_out; meta->comp_size = total_comp; }
    return 0;
}

static int parse_zlib_fmt(const unsigned char *data, size_t len, Buffer *out, Meta *meta, char **errmsg) {
    if (len == 0) { *errmsg = xstrdup("empty"); return -1; }
    memset(meta, 0, sizeof(*meta)); meta->format = 2; meta->method = 8;
    size_t consumed = 0;
    if (!inflate_zlib_to_buf(data, len, out, &consumed)) { *errmsg=xstrdup("unrecognized format"); return -1; }
    if (len >= 4) meta->check = rd32((const unsigned char[]){data[len-1],data[len-2],data[len-3],data[len-4]});
    if (len >= 6) meta->comp_size = len - 6; else meta->comp_size = len;
    meta->orig_size = 0;
    return 0;
}

static time_t dos_to_unix(uint16_t tim, uint16_t dat) {
    struct tm tm; memset(&tm, 0, sizeof(tm));
    tm.tm_sec = (tim & 31) * 2; tm.tm_min = (tim >> 5) & 63; tm.tm_hour = (tim >> 11) & 31;
    tm.tm_mday = dat & 31; tm.tm_mon = ((dat >> 5) & 15) - 1; tm.tm_year = ((dat >> 9) & 127) + 80;
    tm.tm_isdst = -1;
    return mktime(&tm);
}

static void parse_zip_extra_time(const unsigned char *extra, size_t len, uint32_t *mt, bool *has) {
    size_t p = 0;
    while (p + 4 <= len) {
        uint16_t id = rd16(extra+p), sz = rd16(extra+p+2); p += 4;
        if (p + sz > len) break;
        if (id == 0x5455 && sz >= 5 && extra[p] & 1) { *mt = rd32(extra+p+1); *has = true; return; }
        p += sz;
    }
}

static int parse_zip_fmt(const unsigned char *data, size_t len, Buffer *out, Meta *meta, char **errmsg) {
    if (len == 0) { *errmsg=xstrdup("empty"); return -1; }
    if (len < 30 || rd32(data) != 0x04034b50) { *errmsg=xstrdup("unrecognized format"); return -1; }
    memset(meta, 0, sizeof(*meta)); meta->format = 3;
    uint16_t flags = rd16(data+6), method = rd16(data+8), tim = rd16(data+10), dat = rd16(data+12);
    uint32_t hcrc = rd32(data+14), hcsize = rd32(data+18), husize = rd32(data+22);
    uint16_t nlen = rd16(data+26), xlen = rd16(data+28);
    if (30U + nlen + xlen > len) { *errmsg=xstrdup("corrupted"); return -1; }
    char *name = (char*)malloc((size_t)nlen + 1); if (!name) return -1;
    memcpy(name, data+30, nlen); name[nlen] = 0;
    uint32_t mt = (uint32_t)dos_to_unix(tim, dat); bool has = mt != 0;
    parse_zip_extra_time(data+30+nlen, xlen, &mt, &has);
    size_t pos = 30U + nlen + xlen;
    size_t comp_consumed = 0; uint32_t crc = 0; uint64_t csize = hcsize, usize = husize;
    size_t out_before = out->len;
    if (method == 0) {
        if (flags & 8) { free(name); *errmsg=xstrdup("corrupted"); return -1; }
        if (pos + csize > len) { free(name); *errmsg=xstrdup("corrupted"); return -1; }
        buf_append(out, data+pos, (size_t)csize); comp_consumed = (size_t)csize; pos += comp_consumed;
    } else if (method == 8) {
        if (!inflate_raw_to_buf(data+pos, len-pos, out, &comp_consumed)) { free(name); *errmsg=xstrdup("corrupted -- invalid deflate data"); return -1; }
        pos += comp_consumed;
    } else { free(name); *errmsg=xstrdup("unsupported method"); return -1; }
    if (flags & 8) {
        if (pos + 4 <= len && rd32(data+pos) == 0x08074b50) pos += 4;
        if (pos + 12 > len) { free(name); *errmsg=xstrdup("corrupted"); return -1; }
        hcrc = rd32(data+pos); pos += 4;
        /* pigz writes Zip64 descriptors; accept both */
        if (pos + 16 <= len) { csize = rd64(data+pos); usize = rd64(data+pos+8); pos += 16; }
        else { csize = rd32(data+pos); usize = rd32(data+pos+4); pos += 8; }
    }
    crc = crc32(0L, Z_NULL, 0); crc = crc32(crc, out->data + out_before, (uInt)(out->len - out_before));
    if (crc != hcrc) { free(name); *errmsg=xstrdup("corrupted -- crc32 mismatch"); return -1; }
    meta->method = method; meta->check = crc; meta->mtime = mt; meta->has_mtime = has; meta->name = name;
    meta->comp_size = (flags & 8) ? csize : comp_consumed; meta->orig_size = (flags & 8) ? usize : (out->len - out_before);
    return 0;
}

static int decompress_any(const unsigned char *data, size_t len, Buffer *out, Meta *meta, char **errmsg) {
    if (len == 0) { *errmsg = xstrdup("empty"); return -1; }
    if (len >= 2 && data[0] == 0x1f && data[1] == 0x8b) return parse_gzip(data, len, out, meta, false, errmsg);
    if (len >= 4 && data[0] == 'P' && data[1] == 'K' && data[2] == 3 && data[3] == 4) return parse_zip_fmt(data, len, out, meta, errmsg);
    /* try zlib */
    return parse_zlib_fmt(data, len, out, meta, errmsg);
}

static char *strip_compressed_suffix(const char *name) {
    size_t n = strlen(name);
    if (ends_with(name, ".tgz")) { char *s = xstrdup(name); strcpy(s+n-4, ".tar"); return s; }
    const char *sufs[] = {".gz", "-gz", ".z", ".Z", ".zz", ".zip", NULL};
    for (int i=0;sufs[i];i++) if (ends_with(name, sufs[i])) { size_t m=strlen(sufs[i]); char *s=(char*)malloc(n-m+1); if(!s) return NULL; memcpy(s,name,n-m); s[n-m]=0; return s; }
    return NULL;
}

static char *output_suffix(const Options *opt) {
    if (opt->suffix_set) return opt->suffix;
    if (opt->zip_mode) return ".zip";
    if (opt->zlib_mode) return ".zz";
    return ".gz";
}

static void meta_free(Meta *m) { free(m->name); m->name = NULL; }

static void format_time(uint32_t mt, char *buf, size_t buflen) {
    if (mt == 0) { snprintf(buf, buflen, "------ -----"); return; }
    time_t t = (time_t)mt;
    struct tm tmv, nowv;
    localtime_r(&t, &tmv); time_t now = time(NULL); localtime_r(&now, &nowv);
    if (tmv.tm_year == nowv.tm_year) strftime(buf, buflen, "%b %e %H:%M", &tmv);
    else strftime(buf, buflen, "%b %e  %Y", &tmv);
}

static void print_reduction(uint64_t comp, uint64_t orig, bool unk, char *buf, size_t n) {
    if (unk) snprintf(buf, n, "unk");
    else if (orig == 0) snprintf(buf, n, "-inf%%");
    else snprintf(buf, n, "%5.1f%%", 100.0 * (1.0 - (double)comp / (double)orig));
}

static int list_one(const Options *opt, const char *display, const unsigned char *data, size_t len, const char *fallback_name, bool header_printed) {
    (void)header_printed;
    Buffer out; buf_init(&out); Meta meta; memset(&meta,0,sizeof(meta)); char *err=NULL;
    int ok = decompress_any(data, len, &out, &meta, &err);
    if (ok != 0) {
        if (err && strcmp(err,"empty")==0) skip_msg(opt, "%s empty", display);
        else if (err && strcmp(err,"unrecognized format")==0) skip_msg(opt, "%s unrecognized format", display);
        else skip_msg(opt, "%s: %s", display, err ? err : "corrupted");
        free(err); buf_free(&out); meta_free(&meta); return 1;
    }
    const char *name = meta.name && *meta.name ? meta.name : fallback_name;
    char red[32];
    if (meta.format == 3 && (meta.comp_size || meta.orig_size)) {
        /* The reference quick listing reports unknown sizes for streamed zip entries. */
        meta.comp_size = 0; meta.orig_size = 0; meta.orig_unknown = true;
    }
    print_reduction(meta.comp_size, meta.orig_size, meta.orig_unknown, red, sizeof(red));
    if (opt->verbose) {
        char tb[32]; format_time(meta.has_mtime ? meta.mtime : 0, tb, sizeof(tb));
        const char *meth = meta.format == 1 ? "gzip" : meta.format == 2 ? "zlib" : "zip ";
        if (meta.format == 3) printf("%-4s %d  --------  %-12s  %10llu %10llu%s  %-5s  %s\n", meth, meta.method, tb, (unsigned long long)meta.comp_size, (unsigned long long)meta.orig_size, meta.orig_unknown?"?":" ", red, name);
        else printf("%-4s %d  %08x  %-12s  %10llu %10llu%s  %-5s  %s\n", meth, meta.method, meta.check, tb, (unsigned long long)meta.comp_size, (unsigned long long)meta.orig_size, meta.orig_unknown?"?":" ", red, name);
    } else {
        printf("%10llu %10llu%s  %-5s  %s\n", (unsigned long long)meta.comp_size, (unsigned long long)meta.orig_size, meta.orig_unknown?"?":" ", red, name);
    }
    buf_free(&out); meta_free(&meta); return 0;
}

static int process_path(const Options *opt, const char *path, bool dash_file);

static int process_directory(const Options *opt, const char *path) {
    DIR *d = opendir(path);
    if (!d) { skip_msg(opt, "%s does not exist", path); return 1; }
    int rc = 0;
    struct dirent *de;
    while ((de = readdir(d)) != NULL) {
        if (strcmp(de->d_name,".")==0 || strcmp(de->d_name,"..")==0) continue;
        size_t len = strlen(path) + strlen(de->d_name) + 2;
        char *child = (char*)malloc(len); if (!child) { rc=1; continue; }
        snprintf(child, len, "%s/%s", path, de->d_name);
        int r = process_path(opt, child, false); if (r) rc = 1;
        free(child);
    }
    closedir(d);
    return rc;
}

static int compress_to_buffer(const Options *opt, const unsigned char *data, size_t len, const char *name, time_t mtime, bool is_stdin, Buffer *out) {
    if (opt->zip_mode) make_zip(out, data, len, opt, name, mtime, is_stdin);
    else if (opt->zlib_mode) make_zlib_fmt(out, data, len, opt);
    else make_gzip(out, data, len, opt, name, mtime, is_stdin);
    return 0;
}

static int process_stdin(const Options *opt) {
    Buffer in; buf_init(&in);
    if (!read_stream(stdin, &in)) { skip_msg(opt, "<stdin> read error"); buf_free(&in); return 1; }
    if (opt->decompress || opt->list || opt->test) {
        if (in.len == 0) { skip_msg(opt, "<stdin> empty"); buf_free(&in); return 1; }
        if (opt->list) {
            if (opt->verbose) printf("method    check    timestamp    compressed   original reduced  name\n");
            else printf("compressed   original reduced  name\n");
            char *fallback = xstrdup("<stdin>");
            int r = list_one(opt, "<stdin>", in.data, in.len, fallback, true); free(fallback); buf_free(&in); return r;
        }
        Buffer out; buf_init(&out); Meta meta; memset(&meta,0,sizeof(meta)); char *err=NULL;
        int ok = decompress_any(in.data, in.len, &out, &meta, &err);
        if (ok != 0) {
            if (err && strcmp(err,"empty")==0) skip_msg(opt, "<stdin> empty");
            else if (err && strcmp(err,"unrecognized format")==0) skip_msg(opt, "<stdin> unrecognized format");
            else skip_msg(opt, "<stdin>: %s", err ? err : "corrupted");
            free(err); buf_free(&out); buf_free(&in); meta_free(&meta); return 1;
        }
        if (!opt->test) fwrite(out.data, 1, out.len, stdout);
        buf_free(&out); buf_free(&in); meta_free(&meta); return 0;
    } else {
        Buffer out; buf_init(&out); compress_to_buffer(opt, in.data, in.len, NULL, 0, true, &out);
        fwrite(out.data, 1, out.len, stdout);
        buf_free(&out); buf_free(&in); return 0;
    }
}

static int process_compress_file(const Options *opt, const char *path) {
    struct stat st, lst;
    if (lstat(path, &lst) != 0) { skip_msg(opt, "%s does not exist", path); return 1; }
    if (S_ISLNK(lst.st_mode) && !opt->force) { skip_msg(opt, "%s is a symbolic link", path); return 1; }
    if (stat(path, &st) != 0) { skip_msg(opt, "%s does not exist", path); return 1; }
    if (S_ISDIR(st.st_mode)) {
        if (opt->recursive) return process_directory(opt, path);
        skip_msg(opt, "%s is a directory", path); return 1;
    }
    if (!S_ISREG(st.st_mode)) { skip_msg(opt, "%s is not a regular file", path); return 1; }
    const char *suf = output_suffix(opt);
    if (!opt->force && ends_with(path, suf) && !opt->stdout_mode) { skip_msg(opt, "%s ends with %s", path, suf); return 0; }
    Buffer in; buf_init(&in);
    if (!read_file_buf(path, &in)) { skip_msg(opt, "%s read error", path); buf_free(&in); return 1; }
    Buffer out; buf_init(&out); compress_to_buffer(opt, in.data, in.len, path, st.st_mtime, false, &out);
    int rc = 0;
    if (opt->stdout_mode) {
        if (opt->verbose) fprintf(stderr, "%s to <stdout> \n", path);
        fwrite(out.data, 1, out.len, stdout);
    } else {
        size_t on = strlen(path) + strlen(suf) + 1;
        char *outname = (char*)malloc(on); if (!outname) { rc=1; goto done; }
        snprintf(outname, on, "%s%s", path, suf);
        if (!opt->force && access(outname, F_OK) == 0) { skip_msg(opt, "%s exists", outname); free(outname); rc=1; goto done; }
        if (opt->verbose) fprintf(stderr, "%s to %s \n", path, outname);
        if (!write_file_buf(outname, &out, st.st_mode, st.st_mtime, true, opt->syncout)) { skip_msg(opt, "%s write error", outname); free(outname); rc=1; goto done; }
        if (!opt->keep) {
            if (st.st_nlink > 1 && !opt->force) { warn_msg(opt, "%s has hard links -- not unlinking", path); rc = 1; }
            else unlink(path);
        }
        free(outname);
    }
done:
    buf_free(&in); buf_free(&out); return rc;
}

static int process_decompress_file(const Options *opt, const char *path) {
    struct stat st, lst;
    if (lstat(path, &lst) != 0) { skip_msg(opt, "%s does not exist", path); return 1; }
    if (S_ISLNK(lst.st_mode) && !opt->force) { skip_msg(opt, "%s is a symbolic link", path); return 1; }
    if (stat(path, &st) != 0) { skip_msg(opt, "%s does not exist", path); return 1; }
    if (S_ISDIR(st.st_mode)) {
        if (opt->recursive) return process_directory(opt, path);
        skip_msg(opt, "%s is a directory", path); return 1;
    }
    if (!S_ISREG(st.st_mode)) { skip_msg(opt, "%s is not a regular file", path); return 1; }
    char *stripped = strip_compressed_suffix(path);
    if (!opt->stdout_mode && !opt->test && !opt->list && !stripped) { skip_msg(opt, "%s does not have compressed suffix", path); return 1; }
    Buffer in; buf_init(&in);
    if (!read_file_buf(path, &in)) { skip_msg(opt, "%s read error", path); free(stripped); return 1; }
    if (in.len == 0) { skip_msg(opt, "%s empty", path); buf_free(&in); free(stripped); return 1; }
    if (opt->list) {
        char *fallback = stripped ? stripped : xstrdup(path);
        int r = list_one(opt, path, in.data, in.len, fallback, true);
        free(fallback); buf_free(&in); free(stripped); return r;
    }
    Buffer out; buf_init(&out); Meta meta; memset(&meta,0,sizeof(meta)); char *err=NULL;
    int ok = decompress_any(in.data, in.len, &out, &meta, &err);
    if (ok != 0) {
        if (err && strcmp(err,"unrecognized format")==0) skip_msg(opt, "%s unrecognized format", path);
        else if (err && strcmp(err,"empty")==0) skip_msg(opt, "%s empty", path);
        else skip_msg(opt, "%s: %s", path, err ? err : "corrupted");
        free(err); buf_free(&in); buf_free(&out); meta_free(&meta); free(stripped); return 1;
    }
    int rc = 0;
    if (opt->test) {
        /* nothing */
    } else if (opt->stdout_mode) {
        if (opt->verbose) fprintf(stderr, "%s to <stdout> \n", path);
        fwrite(out.data, 1, out.len, stdout);
    } else {
        char *outname = NULL;
        if (opt->save_name && meta.name && *meta.name) outname = xstrdup(meta.name);
        else outname = stripped ? xstrdup(stripped) : xstrdup(path);
        if (!opt->force && access(outname, F_OK) == 0) { skip_msg(opt, "%s exists", outname); free(outname); rc=1; goto done; }
        if (opt->verbose) fprintf(stderr, "%s to %s \n", path, outname);
        time_t out_time = st.st_mtime;
        if (opt->save_time && meta.has_mtime) out_time = (time_t)meta.mtime;
        if (!write_file_buf(outname, &out, st.st_mode, out_time, true, opt->syncout)) { skip_msg(opt, "%s write error", outname); rc=1; free(outname); goto done; }
        if (!opt->keep) {
            if (st.st_nlink > 1 && !opt->force) { warn_msg(opt, "%s has hard links -- not unlinking", path); rc=1; }
            else unlink(path);
        }
        free(outname);
    }
done:
    buf_free(&in); buf_free(&out); meta_free(&meta); free(stripped); return rc;
}

static int process_path(const Options *opt, const char *path, bool dash_file) {
    if (!dash_file && strcmp(path, "-") == 0) return process_stdin(opt);
    if (opt->decompress || opt->list || opt->test) return process_decompress_file(opt, path);
    return process_compress_file(opt, path);
}

int main(int argc, char **argv) {
    Options opt; StrVec files = {0};
    parse_options(argc, argv, &opt, &files);
    if (opt.list) {
        if (opt.verbose) printf("method    check    timestamp    compressed   original reduced  name\n");
        else printf("compressed   original reduced  name\n");
    }
    int rc = 0;
    if (files.n == 0) {
        rc = process_stdin(&opt);
    } else {
        bool dashdash = false;
        /* We do not retain which names followed -- in the token list. For the only
           special case, a literal '-' that exists as a file can be addressed as ./- . */
        (void)dashdash;
        for (int i=0; i<files.n; i++) {
            int r = process_path(&opt, files.v[i], false);
            if (r) rc = 1;
        }
    }
    free(opt.suffix); free(opt.alias); free(opt.comment); free(files.v);
    return rc;
}
